import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import {
  KeepScale,
  TransformComponent,
  TransformWrapper,
} from "react-zoom-pan-pinch";
import { Map as immuMap } from "immutable";
import { styled, SvgIcon } from "@mui/material";
import LocationOnIcon from "@mui/icons-material/LocationOn";
import { pink } from "@mui/material/colors";

const StyledDiv = styled("div")(({ theme }) => ({
  position: "fixed",
  inset: "56px 0 112px 0",
  [`& > .react-transform-wrapper`]: {
    overflow: "visible",
  },
}));

function ImageZoomable({ src, style, onLoad, size, pos }) {
  const _ref = useRef();
  const _zoomRef = useRef();
  const [imgState, setImgState] = useState(
    immuMap({
      containerWidth: 0,
      containerHeight: 0,
      imageNaturalWidth: 0,
      imageNaturalHeight: 0,
    })
  );
  const imageScale = useMemo(() => {
    const containerWidth = imgState.get("containerWidth");
    const containerHeight = imgState.get("containerHeight");
    const imageNaturalWidth = imgState.get("imageNaturalWidth");
    const imageNaturalHeight = imgState.get("imageNaturalHeight");
    if (
      containerWidth === 0 ||
      containerHeight === 0 ||
      imageNaturalWidth === 0 ||
      imageNaturalHeight === 0
    )
      return 0;
    const scale = Math[size === "cover" ? "max" : "min"](
      containerWidth / imageNaturalWidth,
      containerHeight / imageNaturalHeight
    );
    _zoomRef.current?.setTransform(
      containerWidth / 2 - (imageNaturalWidth * scale) / 2,
      containerHeight / 2 - (imageNaturalHeight * scale) / 2,
      scale
    );
    return scale;
  }, [imgState]);

  function handleLoadImg(img) {
    setImgState((v) =>
      v
        .set("imageNaturalWidth", img.naturalWidth)
        .set("imageNaturalHeight", img.naturalHeight)
    );
  }

  useEffect(() => {
    const image = new Image();
    image.onload = () => handleLoadImg(image);
    image.src = src;
  }, [src]);

  useLayoutEffect(() => {
    const _observer = new ResizeObserver((entries) => {
      for (let entry of entries) {
        if (entry.target !== _ref.current) continue;
        setImgState((v) =>
          v
            .set("containerWidth", entry.contentRect.width)
            .set("containerHeight", entry.contentRect.height)
        );
      }
    });
    _observer.observe(_ref.current);
    return () => {
      _observer.disconnect();
    };
  }, []);

  return (
    <StyledDiv ref={_ref} style={style}>
      {imageScale > 0 && (
        <TransformWrapper
          ref={_zoomRef}
          initialScale={imageScale}
          minScale={imageScale}
          maxScale={imageScale * 8}
          centerOnInit={size !== "cover"}

          // centerZoomedOut
        >
          <TransformComponent
            centerOnInit
            wrapperStyle={{
              width: "100%",
              height: "100%",
            }}
          >
            <img src={src} alt="" onLoad={onLoad} />
            {Array.isArray(pos) && (
              <div
                style={{
                  position: "absolute",
                  top: "50%",
                  left: "50%",
                  transform: "translate(-50%, -50%)",
                  zIndex: 2,
                  marginLeft: pos[0],
                  marginTop: pos[1],
                }}
              >
                <KeepScale>
                  <LocationOnIcon
                    sx={{
                      color: pink[500],
                      width: 40,
                      height: 40,
                      filter:`drop-shadow(1px 1px 3px black)`
                    }}
                  />
                </KeepScale>
              </div>
            )}
          </TransformComponent>
        </TransformWrapper>
      )}
    </StyledDiv>
  );
}
export default ImageZoomable;
