import {
  Backdrop,
  Button,
  CircularProgress,
  Divider,
  Fade,
  IconButton,
  List,
  ListItemButton,
  ListItemText,
  Menu,
  Paper,
  Tab,
  Tabs,
  Typography,
  alpha,
  buttonClasses,
  listClasses,
  listItemButtonClasses,
  listItemTextClasses,
  menuClasses,
  paperClasses,
  styled,
} from "@mui/material";
// import PDFRenderer from "../Copmonents/PDFRenderer";
import ImageZoomable from "../Copmonents/ImageZoomable";
import { Fragment, useEffect, useMemo, useState } from "react";
import YoutubePlayer from "../Copmonents/YoutubePlayer";
import CloudOffOutlinedIcon from "@mui/icons-material/CloudOffOutlined";
import { fetch } from "../Utils/fetch";
import MenuIcon from "@mui/icons-material/Menu";
import QrCodeScannerIcon from "@mui/icons-material/QrCodeScanner";
import { useNavStateStore } from "../Store/nav";
import CloseIcon from "@mui/icons-material/Close";
import QRReader from "./QRreader";
import { useLocation, useHistory } from "react-router-dom";
import { green, red, yellow } from "@mui/material/colors";

const StyledDiv = styled("div")(({ theme }) => ({
  width: "100%",
  height: "100%",
  overflow: "hidden",
  display: "flex",
  flexDirection: "column",
  alignItems: "center",
  [`& > .${buttonClasses.root}`]: {
    position: "fixed",
    bottom: theme.spacing(10),
    borderRadius: 4,
  },
}));

function GuideMapPage() {
  const [isLoaded, setLoaded] = useState(0);
  const [data, setData] = useState();
  const [_flPos, setFlPos] = useState({ fl: [], fl_meta: {}, pos: {} });
  const { search } = useLocation();
  const params = useMemo(() => {
    return new URLSearchParams(search);
  }, [search]);

  function handleLoaded() {
    setLoaded(1);
  }

  useEffect(() => {
    Promise.all([
      fetch({
        url: "/mod/fl_pos.json",
      }).then((resp) => {
        const fl = [];
        const pos = {};
        const fl_meta = {};
        resp.data.forEach((i) => {
          fl.push(i.fl);
          fl_meta[i.fl] = i.map;
          pos[i.fl] = i.pos;
        });

        setFlPos({ fl, fl_meta, pos });
      }),
      fetch({ url: "/mod/guide_map.json" }).then((resp) => {
        setData(resp.data);
      }),
    ]).catch(() => {
      setLoaded(-1);
    });
  }, []);

  return (
    <StyledDiv>
      {!!data &&
        (data.type === "video" ? (
          <YoutubePlayer onLoad={handleLoaded} src={data.src} />
        ) : (
          <Fragment>
            <ImageZoomable
              src={`/mod/${
                _flPos.fl_meta[params.get("fl") ?? data.default_fl]
              }`}
              size={data.size}
              onLoad={handleLoaded}
              pos={
                _flPos.pos[params.get("fl") ?? data.default_fl]?.find(
                  (i) => i.t === (params.get("pos") ?? data.default_pos)
                )?.loc
              }
            />
          </Fragment>
        ))}
      {/* <EvnetButton /> */}
      {isLoaded !== 1 && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
          }}
        >
          {isLoaded === 0 ? (
            <CircularProgress />
          ) : (
            <Fragment>
              <CloudOffOutlinedIcon />
              <Typography>네트워크 오류</Typography>
            </Fragment>
          )}
        </div>
      )}
      {isLoaded === 1 && (
        <PositionTools
          floor={params.get("fl") ?? data.default_fl}
          position={params.get("pos") ?? data.default_pos}
          data={_flPos}
        />
      )}
    </StyledDiv>
  );
}

export default GuideMapPage;

const StyledPositionToolsWrapper = styled("div")(({ theme }) => ({
  position: "fixed",
  top: theme.spacing(10),
  left: 0,
  right: 0,
  zIndex: 0,
  display: "inline-flex",
  justifyContent: "center",
  [`& > .${paperClasses.root}.menu`]: { display: "inline-flex" },
}));

const StyledBackdrop = styled(Backdrop)({ backdropFilter: "unset !important" });
const StyledMenuPaper = styled(Paper)({ display: "inline-flex" });

function PositionTools({ data, floor, position: pos }) {
  const [el, setEl] = useState(false);
  const [_floor, setFloor] = useState(floor ?? "1F");
  const [openQR, setOpenQR] = useState(false);
  const history = useHistory();

  const _posList = useMemo(() => data.pos[_floor], [data, _floor]);

  function handleChange(_, val) {
    setFloor(val);
  }
  function handleOpenQR() {
    setOpenQR(true);
  }
  function handleCloseQR() {
    setOpenQR(false);
  }
  function handleClickPos(e) {
    const _position = (e.currentTarget.dataset ?? {}).pos;
    if (_position === undefined) return;

    history.replace(`/?fl=${_floor}&pos=${_position}`);
  }

  return (
    <Fragment>
      <StyledPositionToolsWrapper>
        <Paper className="menu">
          <Button
            onClick={(e) => setEl(e.target)}
          >{`${floor} | ${pos}`}</Button>
          <Menu
            anchorEl={el}
            open={!!el}
            onClose={() => setEl()}
            BackdropComponent={StyledBackdrop}
            anchorOrigin={{
              vertical: "bottom",
              horizontal: "center",
            }}
            transformOrigin={{
              vertical: "top",
              horizontal: "center",
            }}
            slotProps={{
              paper: {
                sx: {
                  [`& .${menuClasses.list}`]: {
                    pt: "0 !important",
                    pb: "0 !important",
                  },
                },
              },
            }}
          >
            <StyledMenuPaper>
              <Tabs
                orientation="vertical"
                variant="scrollable"
                value={_floor}
                onChange={handleChange}
                aria-label="Vertical tabs example"
                sx={{ borderRight: 1, borderColor: "divider" }}
              >
                {data?.fl.map((i) => (
                  <Tab value={i} label={i} />
                ))}
              </Tabs>
              <List sx={{ minWidth: 150 }}>
                {_posList?.map((i) => (
                  <ListItemButton data-pos={i.t} onClick={handleClickPos}>
                    {i.t}
                  </ListItemButton>
                ))}
              </List>
            </StyledMenuPaper>
          </Menu>
          <Divider orientation="vertical" flexItem />
          <IconButton onClick={handleOpenQR}>
            <QrCodeScannerIcon />
          </IconButton>
        </Paper>
      </StyledPositionToolsWrapper>
      {openQR && <QRReader onClose={handleCloseQR} />}
    </Fragment>
  );
}

function EvnetButton() {
  const [isHidden, setHidden] = useNavStateStore((state) => [
    state.isHidden,
    state.setHidden,
  ]);

  function handleCloseEvent() {
    setHidden(false);
  }

  useEffect(() => {
    return () => {
      setHidden(false);
    };
  }, []);

  return (
    <Fragment>
      <Button
        variant="contained"
        size="small"
        startIcon={<MenuIcon />}
        onClick={() => setHidden(!isHidden)}
      >
        이벤트 목록
      </Button>
      <EventPage in={isHidden} onClose={handleCloseEvent} />
    </Fragment>
  );
}

const StyledEventWrapper = styled(Paper)(({ theme }) => ({
  position: "fixed",
  inset: "0",
  zIndex: 1,
  borderRadius: 0,
  paddingTop: theme.spacing(7),
  display: "flex",
  flexDirection: "column",
  overflow: "hidden",
  "@supports (backdrop-filter: blur(5px)) or (-webkit-backdrop-filter: blur(5px))":
    {
      WebkitBackdropFilter: "blur(15px)",
      backdropFilter: "blur(15px)",
      background: alpha(theme.palette.background.paper, 0.7),
    },
  [`& > div.header`]: {
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "space-between",
  },
  [`& .${listClasses.root}`]: {
    overflow: "hidden auto",
  },
  [`& .${listItemButtonClasses.root}`]: {
    display: "flex",
    flexDirection: "column",
    alignItems: "flex-start",
  },
  [`& .${listItemTextClasses.root}`]: {
    width: "100%",
  },
  [`& .${listItemTextClasses.primary}`]: {
    display: "inline-flex",
    alignItems: "flex-start",
    justifyContent: "space-between",
    width: "100%",
  },
  [`& .${listItemTextClasses.secondary}`]: {
    whiteSpace: "pre",
  },
}));
function EventPage({ in: isOpen, onClose }) {
  const [data, setData] = useState([]);
  const history = useHistory();

  function handleClick(e) {
    const { fl, pos } = e.currentTarget.dataset ?? {};

    if (fl === undefined || pos === undefined) return;

    history.replace(`/?fl=${fl}&pos=${pos}`);
    onClose();
  }

  useEffect(() => {
    fetch({ url: "/mod/events.json" }).then((resp) => {
      setData(resp.data);
    });
  }, []);

  return (
    <Fade in={isOpen} direction="up" mountOnEnter unmountOnExit>
      <StyledEventWrapper elevation={0}>
        <div className="header">
          <div style={{ width: 40 }} />
          <Typography variant="h6">이벤트</Typography>
          <IconButton onClick={onClose}>
            <CloseIcon />
          </IconButton>
        </div>
        <List>
          {data.map((i) => (
            <ListItemButton
              data-fl={i.fl}
              data-pos={i.pos}
              onClick={handleClick}
            >
              <ListItemText
                primary={
                  <Fragment>
                    {i.t}
                    <CrowdTypo pos={`${i.fl}_${i.pos}`} />
                  </Fragment>
                }
                secondary={i.sub}
              />
            </ListItemButton>
          ))}
        </List>
      </StyledEventWrapper>
    </Fade>
  );
}

function CrowdTypo({ pos }) {
  const [ct, setCt] = useState();
  // useEffect(() => {
  //   fetch(APIURLs.event.get, { key: pos })
  //     .then((resp) => setCt(resp.data))
  //     .catch(() => {});
  // }, []);
  return ct ? (
    <Paper
      sx={{
        ml: 2,
        display: "inline-flex",
        padding: `0 8px`,
        justifyContent: "center",
        alignItems: "center",
        background:
          ct === "여유" ? green[300] : ct === "보통" ? yellow[300] : red[300],
      }}
    >
      <Typography variant="caption" color="black">
        {ct}
      </Typography>
    </Paper>
  ) : (
    <Fragment />
  );
}
