import CloseIcon from "@mui/icons-material/Close";
import { IconButton, Paper, styled } from "@mui/material";
import QrScanner from "qr-scanner";
import { useEffect, useRef } from "react";
import { useHistory } from "react-router-dom";
const StyledDiv = styled(Paper)(({ theme }) => ({
  position: "fixed",
  inset: 0,
  overflow: "hidden",
  borderRadius: 0,
  [`& > video`]: {
    width: "100%",
    height: "100%",
  },
}));

function QRReader({ onClose }) {
  const videoRef = useRef();
  const history = useHistory();

  useEffect(() => {
    const qrScanner = new QrScanner(
      videoRef.current,
      (result) => {
        const _url = new URL(result.data);
        const _floor = _url.searchParams.get("fl");
        const _position = _url.searchParams.get("pos");
        if (_floor === undefined || _position === undefined) return;
        history.replace(`/?fl=${_floor}&pos=${_position}`);
        onClose();
      },
      { highlightScanRegion: true, highlightCodeOutline: true }
    );
    qrScanner.start();
    return () => {
      qrScanner.stop();
      qrScanner.destroy();
    };
  }, []);

  return (
    <StyledDiv>
      <IconButton
        onClick={onClose}
        sx={{ position: "fixed", top: 56, right: 0, zIndex: 1 }}
      >
        <CloseIcon />
      </IconButton>
      <video ref={videoRef} />
    </StyledDiv>
  );
}

export default QRReader;
