import { create } from "zustand";
import { persist } from "zustand/middleware";

export const useNavStore = create(
  persist(
    (set) => ({
      map_active: false,
      setNav: (v) => set({ map_active: v }),
    }),
    { name: "nav-storage" }
  )
);
export const useNavStateStore = create((set) => ({
  isHidden: false,
  setHidden: (v) => set({ isHidden: v }),
}));
